import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In triangle ABC, an inscribed circle is tangent to side AB at point P. Let AP = {ap} and PB = {pb}. The length of the internal angle bisector from vertex C to side AB is {angle_bisector_length}. Find the perimeter of triangle ABC.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct a valid triangle by choosing tangency lengths x=AP and y=PB,
# then choosing a semiperimeter s > x+y to define sides a=s-x, b=s-y, c=x+y.
# From these, we compute the C-angle bisector length L_c to ensure internal consistency.
# We also avoid trivial/symmetric instances.
for _ in range(1000):
    x = rng.randint(8, 60)
    y = rng.randint(8, 60)
    if x == y:
        continue
    c = x + y
    # Choose t so that s = c + t is reasonably larger than c.
    # Make s not too small to avoid near-degeneracy, and not too large to keep numbers sensible.
    t_min = max(10, c // 3)
    t_max = max(30, c)
    if t_min >= t_max:
        t_min = 10
        t_max = 40
    t = rng.randint(t_min, t_max)
    s = c + t
    a = s - x
    b = s - y
    # Compute angle bisector length from C to AB: L_c^2 = ab * (1 - c^2/(a+b)^2)
    denom = a + b
    if denom <= 0:
        continue
    L2 = a * b * (1.0 - (c * c) / (denom * denom))
    if L2 <= 0:
        # near-degenerate or invalid; retry
        continue
    L = L2 ** 0.5
    # Avoid trivially nice values (integral L) to increase difficulty
    if abs(round(L) - L) < 1e-9:
        continue
    # Final sanity checks
    if not (x > 0 and y > 0 and L > 0 and s > c):
        continue
    return {
        'ap': x,
        'pb': y,
        'angle_bisector_length': float(L)
    }
# Fallback hard-coded valid instance if random attempts fail
x, y = 17, 31
c = x + y
s = c + 50
a = s - x
b = s - y
denom = a + b
L2 = a * b * (1.0 - (c * c) / (denom * denom))
L = L2 ** 0.5
return {'ap': x, 'pb': y, 'angle_bisector_length': float(L)}

    def verifier(assign):
# Validate required fields
if not isinstance(assign, dict):
    # invalid input format
    return (False, None)  # invalid
keys = ['ap', 'pb', 'angle_bisector_length']
for k in keys:
    if k not in assign:
        # missing key
        return (False, None)
try:
    x = float(assign['ap'])
    y = float(assign['pb'])
    L = float(assign['angle_bisector_length'])
except Exception:
    return (False, None)
# Domain checks
if not (x > 0 and y > 0 and L > 0):
    return (False, None)
if abs(x - y) < 1e-12:
    # avoid symmetric triviality
    return (False, None)
c = x + y
# We must solve for the semiperimeter s > c using the identity derived from the angle bisector:
# L^2 (2s - c)^2 = 4 s (s - c) (s - x) (s - y).
# Define f(s) = L^2 (2s - c)^2 - 4 s (s - c) (s - x) (s - y) and find root s > c.
def f(s):
    return (L*L) * (2.0*s - c)**2 - 4.0 * s * (s - c) * (s - x) * (s - y)
# Bracket the root: at s -> c+, f(s) > 0; for large s, f(s) ~ 4 L^2 s^2 - 4 s^4 -> negative.
left = c + 1e-9
f_left = f(left)
if not (f_left > 0):
    # Numerical issues; try nudging
    left = c + 1e-6
    f_left = f(left)
    if not (f_left > 0):
        # Cannot bracket
        return (False, None)
right = max(2.0*c, c + 1.0)
f_right = f(right)
attempts = 0
while f_right > 0 and attempts < 60:
    right = right * 2.0
    f_right = f(right)
    attempts += 1
if f_right > 0:
    # failed to find bracket
    return (False, None)
# Bisection to find s
for _ in range(80):
    mid = 0.5 * (left + right)
    f_mid = f(mid)
    if abs(f_mid) < 1e-12:
        left = right = mid
        break
    if f_mid > 0:
        left = mid
    else:
        right = mid
s = 0.5 * (left + right)
# Validate s: positive sides and triangle inequality
a = s - x
b = s - y
if not (s > c and a > 0 and b > 0):
    return (False, None)
# Compute perimeter
answer = 2.0 * s
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

